<template>
  <label
    class="fu-button-tab"
    :class="[
      `fu-button-tab--${size}`,
      {
        'is-checked': isChecked,
        'is-disabled': disabled,
        'is-readonly': readonly,
      },
    ]"
    :style="colorStyle"
  >
    <input
      type="radio"
      class="fu-button-tab__input"
      :name="name"
      :value="value"
      :disabled="disabled"
      :checked="isChecked"
      :aria-readonly="readonly"
      @click="handleClick"
      @change="handleChange"
    />

    <!-- Radio indicator -->
    <span class="fu-button-tab__control" aria-hidden="true">
      <span class="fu-button-tab__dot" v-if="isChecked" />
    </span>

    <!-- Title + description -->
    <span class="fu-button-tab__content">
      <span v-if="title || $slots.title" class="fu-button-tab__title">
        <slot name="title">{{ title }}</slot>
      </span>

      <span
        v-if="description || $slots.description"
        class="fu-button-tab__description"
      >
        <slot name="description">{{ description }}</slot>
      </span>

      <slot />
    </span>
  </label>
</template>

<script setup lang="ts">
import { computed } from "vue";

type Size = "sm" | "md" | "lg";

interface Props {
  modelValue?: string | number;
  value: string | number;
  title?: string;
  description?: string;
  name?: string;
  size?: Size;
  disabled?: boolean;
  readonly?: boolean;
  /* Accent color for the ring, dot, border and tint once checked */
  color?: string;
}

const props = withDefaults(defineProps<Props>(), {
  size: "md",
  disabled: false,
  readonly: false,
  title: undefined,
  description: undefined,
  name: undefined,
  color: undefined,
});

const emit = defineEmits(["update:modelValue"]);

const isChecked = computed(() => props.modelValue === props.value);

const colorStyle = computed(() =>
  props.color ? { "--fu-button-tab-accent": props.color } : {}
);

/* -----------------------------------------------------------
   Readonly handling — same approach as FusionRadio: native radios
   ignore readonly, so block the click and never emit.
----------------------------------------------------------- */

function handleClick(e: MouseEvent) {
  if (props.readonly) {
    e.preventDefault();
  }
}

function handleChange() {
  if (props.readonly) return;
  emit("update:modelValue", props.value);
}
</script>

