<template>
  <aside class="pts-root">
    <div class="pts-header">
      <span class="pts-header__label">DOCUMENTS: 1</span>
      <button type="button" class="pts-header__icon" @click="$emit('close')">
        <X :size="16" />
      </button>
    </div>

    <button type="button" class="pts-doc-header" @click="expanded = !expanded">
      <span class="pts-doc-header__text">
        <span class="pts-doc-header__title">{{ title }}</span>
        <span class="pts-doc-header__count"
          >{{ pages.length }} page{{ pages.length === 1 ? "" : "s" }}</span
        >
      </span>
      <ChevronUp v-if="expanded" :size="14" />
      <ChevronDown v-else :size="14" />
    </button>

    <div v-if="expanded" class="pts-list">
      <button
        v-for="(page, i) in pages"
        :key="page.id"
        type="button"
        class="pts-item"
        :class="{ 'pts-item--active': i === activePageIndex }"
        @click="$emit('select-page', i)"
      >
        <span class="pts-item__num">{{ i + 1 }}</span>
        <span class="pts-item__thumb">
          <span class="pts-item__thumb-scale" :ref="(el) => (thumbHostEls[page.id] = el)">
            <FuDocumentRenderer :document="{ pages: [page] }" />

            <FieldCaptureOverlay
              :pages="[page]"
              :recipient="recipient"
              :recipients="recipients"
              :read-only="true"
              :host-el="thumbHostEls[page.id] || null"
            />
          </span>
        </span>
      </button>
    </div>
  </aside>
</template>

<script setup>
import { ref, reactive } from "vue";
import { X, ChevronUp, ChevronDown } from "lucide-vue-next";
import FuDocumentRenderer from "../../renderer/DocumentRenderer.vue";
import FieldCaptureOverlay from "./FieldCaptureOverlay.vue";

defineProps({
  pages: { type: Array, default: () => [] },
  title: { type: String, default: "" },
  activePageIndex: { type: Number, default: -1 },
  recipient: { type: Object, default: null },
  recipients: { type: Array, default: () => [] },
});
defineEmits(["select-page", "close"]);

const expanded = ref(true);
const thumbHostEls = reactive({});
</script>

