<template>
  <FusionModal
    :isVisible="isVisible"
    title="Upload file"
    size="md"
    @close="$emit('close')"
  >
    <FusionUpload
      multiple
      accept="image/*,application/pdf"
      :maxFiles="3"
      :maxFileSizeMB="10"
      @filesSelected="handleFiles"
      @uploadError="handleError"
    />
    <p v-if="error" class="fucm-error">{{ error }}</p>
  </FusionModal>
</template>

<script setup>
import { ref } from "vue";
import FusionModal from "../../modal/FusionModal.vue";
import FusionUpload from "../../fileUploader/FusionUpload.vue";

defineProps({
  isVisible: { type: Boolean, default: false },
});
const emit = defineEmits(["close", "uploaded"]);

const error = ref("");

function handleFiles(files) {
  error.value = "";
  const file = files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    emit("uploaded", {
      name: file.name,
      size: file.size,
      type: file.type,
      dataUrl: reader.result,
    });
    emit("close");
  };
  reader.readAsDataURL(file);
}

function handleError(message) {
  error.value = message;
}
</script>

<style scoped>
.fucm-error {
  margin: 10px 0 0;
  font-size: 13px;
  color: #dc2626;
}
</style>
