<template>
  <div class="fu-viewer">
    <div class="fu-viewer__header">
      <div class="fu-viewer__header-left">
        <FileText :size="18" class="fu-viewer__header-icon" />
        <div class="fu-viewer__header-text">
          <span class="fu-viewer__header-title">{{ title }}</span>
          <span v-if="author" class="fu-viewer__header-author">by {{ author }}</span>
        </div>
      </div>
      <div class="fu-viewer__header-right">
        <span
          v-for="r in recipients"
          :key="r.id"
          class="fu-viewer__avatar"
          :style="{ backgroundColor: r.color }"
          :title="r.name"
        >
          {{ initialsFor(r.name) }}
        </span>
        <div class="fu-viewer__more">
          <button
            type="button"
            class="fu-viewer__more-btn"
            @click="moreActionsOpen = true"
          >
            <span class="fu-viewer__more-label">More actions</span>
            <ChevronDown :size="14" />
          </button>
        </div>
      </div>
    </div>

    <MoreActionsDrawer
      :open="moreActionsOpen"
      :title="title"
      :author="author"
      :recipients="recipients"
      @close="moreActionsOpen = false"
      @toggle-documents="onToggleDocumentsAction"
      @download="$emit('download')"
      @decline="$emit('decline')"
    />

    <!-- Lifecycle notice takes this slot when set (read-only states); otherwise the
     live required-fields prompt shows during signing. -->
    <div
      v-if="notice"
      class="fu-viewer__notice"
      :class="`fu-viewer__notice--${notice.variant}`"
    >
      {{ notice.text }}
    </div>

    <div v-else-if="requiredRemaining.length" class="fu-viewer__required-bar">
      <div class="fu-viewer__required-bar-left">
        <FileCheck :size="16" />
        <span
          >Please fill in {{ requiredRemaining.length }} required field{{
            requiredRemaining.length === 1 ? "" : "s"
          }}.</span
        >
      </div>
      <button type="button" class="fu-viewer__start-btn" @click="onStart">Start</button>
    </div>

    <div class="fu-viewer__body">
      <div
        v-if="sidebarOpen"
        class="fu-viewer__sidebar-backdrop"
        @click="sidebarOpen = false"
      />

      <PageThumbnailStrip
        v-if="sidebarOpen"
        :pages="document?.pages || []"
        :title="title"
        :recipient="recipient"
        :recipients="recipients"
        @select-page="onSelectPage"
        @close="sidebarOpen = false"
      />

      <div class="fu-viewer__main">
        <div class="fu-viewer__main-subheader">
          <span class="fu-viewer__main-title">{{ title }}</span>
          <span class="fu-viewer__main-count">1 of 1 document</span>
        </div>

        <div class="fu-viewer__main-doc">
          <ContractRenderer
            ref="rendererRef"
            :document="document"
            :recipient="recipient"
            :recipients="recipients"
            :read-only="readOnly"
            @update:captured-fields="(v) => (capturedFields = v)"
            @action="(e) => $emit('action', e)"
          />
        </div>
      </div>
    </div>

    <div v-if="!readOnly" class="fu-viewer__finish-bar">
      <span class="fu-viewer__finish-bar-text">
        When you are done reviewing the document, please click
        <strong>Finish</strong> button.
      </span>
      <ArrowRight :size="16" class="fu-viewer__finish-bar-arrow" />
      <button
        type="button"
        class="fu-viewer__finish-btn"
        :disabled="requiredRemaining.length > 0"
        @click="$emit('finish', capturedFields)"
      >
        Finish
      </button>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted } from "vue";
import { FileText, FileCheck, ChevronDown, ArrowRight } from "lucide-vue-next";
import { canRecipientAct } from "./Contract/recipientColor.js";
import ContractRenderer from "./Contract/ContractRenderer.vue";
import PageThumbnailStrip from "./Contract/PageThumbnailStrip.vue";
import MoreActionsDrawer from "./components/MoreActionsDrawer.vue";

const props = defineProps({
  document: { type: Object, default: null },
  recipient: { type: Object, default: null },
  recipients: { type: Array, default: () => [] },
  title: { type: String, default: "" },
  author: { type: String, default: "" },
  readOnly: { type: Boolean, default: false },
  notice: { type: Object, default: null }, // { variant: 'info'|'success'|'error', text }
});
defineEmits(["action", "finish", "decline", "download"]);

const rendererRef = ref(null);
const capturedFields = ref([]);
const moreActionsOpen = ref(false);

const sidebarOpen = ref(true);
onMounted(() => {
  if (window.innerWidth < 768) sidebarOpen.value = false;
});

function onToggleDocumentsAction() {
  sidebarOpen.value = !sidebarOpen.value;
  moreActionsOpen.value = false;
}

function initialsFor(name) {
  const parts = (name || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return (parts[0][0] + (parts[1]?.[0] || "")).toUpperCase();
}

const requiredFields = computed(() => {
  if (!canRecipientAct(props.recipient)) return [];
  const list = [];
  for (const page of props.document?.pages || []) {
    for (const field of page.fields || []) {
      if (field.required && field.recipientId === props.recipient?.id) list.push(field);
    }
  }
  return list;
});

const filledFieldIds = computed(
  () =>
    new Set(
      capturedFields.value
        .filter((f) => f.value !== undefined && f.value !== null && f.value !== "")
        .map((f) => f.fieldId)
    )
);

const requiredRemaining = computed(() =>
  requiredFields.value.filter((f) => !filledFieldIds.value.has(f.id))
);

function onStart() {
  const next = requiredRemaining.value[0];
  if (!next) return;
  rendererRef.value?.focusField(next.id);
}

watch(requiredRemaining, (next, prev) => {
  if (prev && next.length > 0 && next.length < prev.length) {
    rendererRef.value?.focusField(next[0].id);
  }
});

function onSelectPage(index) {
  rendererRef.value?.scrollToPage(index);
}
</script>

