<template>
  <div class="fu-listview" ref="listviewRef">
    <div class="fu-listview__table-wrapper customScrollBar" ref="tableWrapper">
      <table>
        <!-- HEADER -->
        <thead v-if="showHeader">
          <tr>
            <th
              v-if="options?.selectable"
              class="fu-listview__th fu-listview__th--checkbox"
            >
              <div v-if="loading" class="fu-skeleton-cell fu-skeleton-cell--checkbox" />
              <FusionCheckbox v-else v-model="allSelected" size="sm" />
            </th>
            <th
              v-for="col in internalColumns"
              :key="col.key"
              :style="{ width: col.width || 'auto' }"
              class="fu-listview__th"
              :class="[
                `align-${col.textAlign || 'justify'}`,
                {
                  'is-dragging': draggingKey === col.key,
                  'is-drag-over': dragOverKey === col.key && draggingKey !== col.key,
                },
              ]"
              :draggable="editMode && !loading"
              @dragstart="onDragStart($event, col.key)"
              @dragover="onDragOver($event, col.key)"
              @dragleave="onDragLeave(col.key)"
              @drop="onDrop($event, col.key)"
              @dragend="onDragEnd"
            >
              <div
                class="fu-listview__th-content"
                :class="`align-${col.textAlign || 'justify'}`"
              >
                <!-- drag handle (edit mode only) -->
                <span
                  v-if="editMode && !loading"
                  class="fu-listview__drag-handle"
                  title="Drag to reorder"
                  >⠿</span
                >

                <!-- skeleton label -->
                <div v-if="loading" class="fu-skeleton-cell fu-skeleton-cell--header" />
                <!-- real label -->
                <div
                  v-else
                  class="fu-listview__th-sortable"
                  :class="{
                    'is-sortable': !!col.sortable,
                    'is-active': activeSortKey === col.key,
                  }"
                  :role="col.sortable ? 'button' : undefined"
                  :tabindex="col.sortable ? 0 : -1"
                  @click="onHeaderClick(col)"
                  @keydown.enter.prevent="onHeaderClick(col)"
                  @keydown.space.prevent="onHeaderClick(col)"
                >
                  <component
                    v-if="col.icon"
                    :is="col.icon"
                    class="fu-listview__th-icon"
                  />
                  <span class="fu-listview__th-label">{{ col.label }}</span>
                  <!-- sort indicator: always shown on sortable cols -->
                  <span v-if="col.sortable" class="fu-listview__sort-indicator">
                    <template v-if="activeSortKey === col.key">
                      {{ activeSortDirection === "asc" ? "▲" : "▼" }}
                    </template>
                    <template v-else>⇅</template>
                  </span>
                </div>
                <span
                  v-if="options?.resizeColumn && !loading"
                  class="fu-listview__resize-handle"
                  @mousedown.stop="startResize($event, col.key)"
                ></span>
              </div>
            </th>
          </tr>
        </thead>
        <!-- BODY: LOADING -->
        <tbody v-if="loading">
          <tr
            v-for="i in skeletonRows"
            :key="`skeleton-${i}`"
            class="fu-listview__row fu-listview__row--skeleton"
          >
            <td
              v-if="options?.selectable"
              class="fu-listview__td fu-listview__td--checkbox"
            >
              <div class="fu-skeleton-cell fu-skeleton-cell--checkbox" />
            </td>
            <td
              v-for="col in internalColumns"
              :key="`skeleton-${i}-${col.key}`"
              class="fu-listview__td"
              :style="{ width: col.width }"
              :class="{
                'is-dragging': draggingKey === col.key,
                'is-drag-over': dragOverKey === col.key && draggingKey !== col.key,
              }"
            >
              <div
                class="fu-skeleton-cell"
                :style="{ width: skeletonWidth(i, col.key) }"
              />
            </td>
          </tr>
        </tbody>
        <!-- BODY: REAL DATA -->
        <tbody v-else>
          <tr
            v-for="row in rows"
            :key="row[rowKey]"
            class="fu-listview__row"
            @click="handleRowClick(row)"
          >
            <td
              v-if="options?.selectable"
              class="fu-listview__td fu-listview__td--checkbox"
              @click.stop
            >
              <FusionCheckbox
                v-model="row.__selected"
                @change="emitSelectionChange"
                size="sm"
                :disabled="!isSelectable(row)"
              />
            </td>
            <slot name="tableRow" :row="row">
              <td
                v-for="col in internalColumns"
                :key="col.key"
                class="fu-listview__td"
                :style="{ width: col.width }"
                :class="[
                  `align-${col.textAlign || 'justify'}`,
                  {
                    'is-dragging': draggingKey === col.key,
                    'is-drag-over': dragOverKey === col.key && draggingKey !== col.key,
                  },
                ]"
              >
                <slot :name="`cell-${col.key}`" :row="row" :col="col">
                  <span class="fu-listview__cell">{{ row[col.key] }}</span>
                </slot>
              </td>
            </slot>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>
<script setup lang="ts">
import { ref, watch, computed, onMounted, onBeforeUnmount } from "vue";
import FusionCheckbox from "@/components/checkbox/FusionCheckbox.vue";

export type SortDirection = "asc" | "desc";

export interface ListColumn {
  label: string;
  key: string;
  width?: string;
  icon?: any;
  textAlign?: "start" | "center" | "end" | "justify";
  sortable?: boolean;
  visible?: boolean; // defaults to true
  orderPosition?: number; // defaults to original array index
}

const props = defineProps<{
  columns: ListColumn[];
  rows: Record<string, any>[];
  rowKey: string;
  showHeader?: boolean;
  loading?: boolean;
  skeletonRows?: number;
  editMode?: boolean;
  sort?: {
    key: string | null;
    direction: SortDirection;
  } | null;
  options?: {
    onRowClick?: (row: any) => void;
    selectable?: boolean;
    resizeColumn?: boolean;
    sortable?: boolean;
    isRowSelectable?: (row: any) => boolean;
  };
}>();

const emit = defineEmits<{
  (e: "row-selected", selectedRows: any[]): void;
  (e: "row-clicked", clickedRow: any): void;
  (e: "sort-change", payload: { key: string; direction: SortDirection }): void;
  (e: "columns-reordered", columns: { key: string; orderPosition: number }[]): void;
}>();

/* -----------------------------
   SKELETON WIDTHS
-------------------------------- */
const widthSets = [
  ["55%", "70%", "40%", "65%", "50%"],
  ["75%", "45%", "80%", "55%", "60%"],
  ["60%", "80%", "50%", "70%", "45%"],
  ["45%", "65%", "75%", "40%", "70%"],
  ["70%", "50%", "60%", "80%", "55%"],
];
function skeletonWidth(rowIndex: number, colKey: string): string {
  const colIndex = internalColumns.value.findIndex((c) => c.key === colKey) % 5;
  return widthSets[(rowIndex - 1) % widthSets.length][colIndex];
}

/* -----------------------------
   INTERNAL STATE
-------------------------------- */
const skeletonRows = computed(() => props.skeletonRows ?? 8);

// runtime width overrides from manual resize, keyed by column key
// (keyed by key, not index, so widths survive reordering)
const widthOverrides = ref<Record<string, string>>({});

const internalColumns = computed(() => {
  return props.columns
    .map((col, index) => ({
      ...col,
      width: widthOverrides.value[col.key] || col.width || "150px",
      textAlign: col.textAlign || "justify",
      sortable: !!col.sortable,
      visible: col.visible !== false,
      orderPosition: col.orderPosition ?? index,
    }))
    .filter((col) => col.visible)
    .sort((a, b) => a.orderPosition - b.orderPosition);
});

const allSelected = ref(false);
const listviewRef = ref<HTMLElement | null>(null);
const tableWrapper = ref<HTMLElement | null>(null);

const internalSortKey = ref<string | null>(null);
const internalSortDirection = ref<SortDirection>("asc");
const isControlledSort = computed(() => !!props.sort);
const activeSortKey = computed(() =>
  isControlledSort.value ? props.sort?.key ?? null : internalSortKey.value
);
const activeSortDirection = computed(() =>
  isControlledSort.value ? props.sort?.direction ?? "asc" : internalSortDirection.value
);

const showHeader = props.showHeader ?? true;
const isSortingEnabled = () => props.options?.sortable !== false;

/* -----------------------------
   SELECTION
-------------------------------- */
function isSelectable(row: any) {
  if (!props.options?.selectable) return false;
  if (props.options?.isRowSelectable) return props.options.isRowSelectable(row);
  return true;
}
function emitSelectionChange() {
  const selected = props.rows.filter((r) => r.__selected && isSelectable(r));
  emit("row-selected", selected);
}
watch(allSelected, (val) => {
  if (!props.options?.selectable) return;
  props.rows.forEach((row) => {
    if (isSelectable(row)) row.__selected = val;
  });
  emitSelectionChange();
});

/* -----------------------------
   SORTING
-------------------------------- */
function onHeaderClick(col: { key: string; sortable?: boolean }) {
  if (props.editMode) return; // don't sort while reordering columns
  if (!isSortingEnabled()) return;
  if (!col.sortable) return;

  const currentKey = activeSortKey.value;
  const currentDirection = activeSortDirection.value;
  let newDirection: SortDirection = "asc";

  if (currentKey === col.key) {
    newDirection = currentDirection === "asc" ? "desc" : "asc";
  }

  if (!isControlledSort.value) {
    internalSortKey.value = col.key;
    internalSortDirection.value = newDirection;
  }

  emit("sort-change", { key: col.key, direction: newDirection });
}

/* -----------------------------
   ROW CLICK
-------------------------------- */
function handleRowClick(row: any) {
  emit("row-clicked", row);
  props.options?.onRowClick?.(row);
}

/* -----------------------------
   RESIZE (keyed by column key, not index)
-------------------------------- */
let resizingKey: string | null = null;
let startX = 0;
let startWidth = 0;

function startResize(e: MouseEvent, colKey: string) {
  if (!props.options?.resizeColumn) return;
  resizingKey = colKey;
  startX = e.clientX;
  const col = internalColumns.value.find((c) => c.key === colKey);
  startWidth = parseInt((col?.width as string) || "150", 10);
  document.addEventListener("mousemove", onResize);
  document.addEventListener("mouseup", stopResize);
}
function onResize(e: MouseEvent) {
  if (!resizingKey) return;
  const delta = e.clientX - startX;
  widthOverrides.value[resizingKey] = `${Math.max(60, startWidth + delta)}px`;
}
function stopResize() {
  resizingKey = null;
  document.removeEventListener("mousemove", onResize);
  document.removeEventListener("mouseup", stopResize);
}

/* -----------------------------
   DRAG TO REORDER (edit mode)
-------------------------------- */
const draggingKey = ref<string | null>(null);
const dragOverKey = ref<string | null>(null);

function onDragStart(e: DragEvent, colKey: string) {
  if (!props.editMode) return;
  draggingKey.value = colKey;
  e.dataTransfer?.setData("text/plain", colKey);
  if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
}

function onDragOver(e: DragEvent, colKey: string) {
  if (!props.editMode || !draggingKey.value) return;
  e.preventDefault(); // required to allow drop
  dragOverKey.value = colKey;
}

function onDragLeave(colKey: string) {
  if (dragOverKey.value === colKey) dragOverKey.value = null;
}

function onDrop(e: DragEvent, targetKey: string) {
  if (!props.editMode || !draggingKey.value) return;
  e.preventDefault();

  const sourceKey = draggingKey.value;
  draggingKey.value = null;
  dragOverKey.value = null;
  if (sourceKey === targetKey) return;

  const ordered = [...internalColumns.value];
  const fromIndex = ordered.findIndex((c) => c.key === sourceKey);
  const toIndex = ordered.findIndex((c) => c.key === targetKey);
  if (fromIndex === -1 || toIndex === -1) return;

  const [moved] = ordered.splice(fromIndex, 1);
  ordered.splice(toIndex, 0, moved);

  const payload = ordered.map((c, i) => ({ key: c.key, orderPosition: i }));
  emit("columns-reordered", payload);
}

function onDragEnd() {
  draggingKey.value = null;
  dragOverKey.value = null;
}

/* -----------------------------
   SCROLL FIX
-------------------------------- */
function wakeScroll() {
  const el = tableWrapper.value;
  if (!el) return;
  el.style.overflowY = "hidden";
  requestAnimationFrame(() => {
    el.style.overflowY = "auto";
  });
}
onMounted(() => {
  wakeScroll();
  window.addEventListener("resize", wakeScroll);
});
onBeforeUnmount(() => {
  window.removeEventListener("resize", wakeScroll);
  document.removeEventListener("mousemove", onResize);
  document.removeEventListener("mouseup", stopResize);
});
</script>
<style scoped lang="scss">
@use "ListView.scss";

.fu-listview__th-sortable {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  user-select: none;
}
.fu-listview__th-sortable.is-sortable {
  cursor: pointer;
}
.fu-listview__th-sortable:not(.is-sortable) {
  cursor: default;
  opacity: 0.9;
}

/* ── Sort indicator ─────────────────────────────────────── */
.fu-listview__sort-indicator {
  font-size: 10px;
  opacity: 0.35;
  transition: opacity 0.15s ease;
}
.fu-listview__th-sortable.is-active .fu-listview__sort-indicator {
  opacity: 1;
  color: var(--fu-color-text);
}
.fu-listview__th-sortable.is-sortable:hover .fu-listview__sort-indicator {
  opacity: 0.7;
}

/* ── Alignment ──────────────────────────────────────────── */
.align-start {
  text-align: left !important;
  justify-content: flex-start !important;
}
.align-center {
  text-align: center !important;
  justify-content: center !important;
}
.align-end {
  text-align: right !important;
  justify-content: flex-end !important;
}
.align-justify {
  text-align: justify !important;
  justify-content: space-between !important;
}

/* ── Drag to reorder ────────────────────────────────────── */
.fu-listview__drag-handle {
  cursor: grab;
  opacity: 0.5;
  padding: 0 4px;
  font-size: 14px;
  user-select: none;
  &:active {
    cursor: grabbing;
  }
}
/* whole-column feedback: applies to the th AND every td in that column */
.fu-listview__th.is-dragging,
.fu-listview__td.is-dragging {
  opacity: 0.4;
  background: color-mix(in srgb, var(--fu-color-primary, #4a7dff) 6%, transparent);
}
.fu-listview__th.is-drag-over,
.fu-listview__td.is-drag-over {
  background: color-mix(in srgb, var(--fu-color-primary, #4a7dff) 10%, transparent);
  box-shadow: inset 2px 0 0 var(--fu-color-primary, #4a7dff);
  transition: background 0.1s ease;
}

/* ── Skeleton ───────────────────────────────────────────── */
@keyframes shimmer {
  0% {
    background-position: -600px 0;
  }
  100% {
    background-position: 600px 0;
  }
}
.fu-listview__row--skeleton {
  pointer-events: none;
}
.fu-skeleton-cell {
  height: 14px;
  border-radius: 6px;
  background: linear-gradient(
    90deg,
    var(--fu-skeleton) 25%,
    color-mix(in srgb, var(--fu-skeleton) 40%, transparent) 50%,
    var(--fu-skeleton) 75%
  );
  background-size: 600px 100%;
  animation: shimmer 1.4s ease-in-out infinite;
}
.fu-skeleton-cell--checkbox {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  margin: 0 auto;
}
.fu-skeleton-cell--header {
  height: 12px;
  width: 60%;
  border-radius: 6px;
}
.fu-listview__td--checkbox,
.fu-listview__th--checkbox {
  width: 40px;
  min-width: 40px;
  max-width: 40px;
}
</style>
