const WEB_SAFE_FONTS = new Set([
  "Arial",
  "Georgia",
  "Times New Roman",
  "Courier New",
  "Verdana",
  "Tahoma",
  "Trebuchet MS",
  "Helvetica",
  "Impact",
  "Comic Sans MS",
]);

const loadedFonts = new Set<string>();

export function loadGoogleFont(fontName: string): void {
  if (!fontName || WEB_SAFE_FONTS.has(fontName) || loadedFonts.has(fontName)) return;
  loadedFonts.add(fontName);

  const family = encodeURIComponent(fontName).replace(/%20/g, "+");
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = `https://fonts.googleapis.com/css2?family=${family}:wght@400;500;600;700&display=swap`;
  document.head.appendChild(link);
}
