<template>
  <div ref="hostEl" class="contract-renderer" :style="rendererStyle">
    <FuDocumentRenderer
      v-if="document"
      :document="document"
      @action="(e) => emit('action', e)"
    />
    <FieldCaptureOverlay
      ref="overlayRef"
      :pages="document?.pages || []"
      :recipient="recipient"
      :recipients="recipients"
      :read-only="readOnly"
      :host-el="hostEl"
      @update:captured-fields="(v) => emit('update:capturedFields', v)"
    />
  </div>
</template>

<script setup>
import { ref, computed, watchEffect, onMounted, onBeforeUnmount } from "vue";
import FuDocumentRenderer from "../../renderer/DocumentRenderer.vue";
import FieldCaptureOverlay from "./FieldCaptureOverlay.vue";
import { getPageLayoutStyle, getPageDimensions } from "./pageDimensions.js";
import { preloadDocumentFonts } from "../../../utils/preloadDocumentFonts";

const props = defineProps({
  document: { type: Object, default: null },
  recipient: { type: Object, default: null },
  recipients: { type: Array, default: () => [] },
  readOnly: { type: Boolean, default: false },
});
const emit = defineEmits(["update:capturedFields", "action"]);

const hostEl = ref(null);
const overlayRef = ref(null);

watchEffect(() => preloadDocumentFonts(props.document));

// ── Mobile scale ──────────────────────────────────────────────────────────────
// Apply CSS zoom to the entire renderer (pages + field overlay) so both scale
// uniformly on narrow screens. Since fc-root and page-renderer elements share
// the same zoomed coordinate space, offset-based field positioning in
// FieldCaptureOverlay continues to work with no changes there.
const parentWidth = ref(0);
let scaleRo = null;

onMounted(() => {
  const parent = hostEl.value?.parentElement;
  if (!parent) return;
  scaleRo = new ResizeObserver(([e]) => { parentWidth.value = e.contentRect.width; });
  scaleRo.observe(parent);
});
onBeforeUnmount(() => scaleRo?.disconnect());

const mobileZoom = computed(() => {
  const layout = props.document?.meta?.pageLayout ?? {};
  if (layout.pageSize === "full") return 1;
  const { w } = getPageDimensions(layout.pageSize, layout.orientation);
  if (!parentWidth.value || !w) return 1;
  return Math.min(1, parentWidth.value / w);
});

const rendererStyle = computed(() => {
  const layout = props.document?.meta?.pageLayout ?? {};
  const base = getPageLayoutStyle(layout.pageSize, layout.orientation);
  if (layout.pageSize === "full") return base;
  const h = base.minHeight ?? "1123px";
  return {
    ...base,
    minHeight: undefined,
    "--page-min-height": h,
    ...(mobileZoom.value < 1 ? { zoom: mobileZoom.value } : {}),
  };
});

function scrollToPage(index) {
  const pageEls = hostEl.value?.querySelectorAll(".page-renderer");
  pageEls?.[index]?.scrollIntoView({ behavior: "smooth", block: "start" });
}

defineExpose({
  focusField: (fieldId) => overlayRef.value?.focusField(fieldId),
  scrollToPage,
});
</script>

<style scoped>
.contract-renderer {
  position: relative;
}

.contract-renderer :deep(.page-renderer) {
  min-height: var(--page-min-height, 1123px) !important;
}
</style>
