// Shared field-type definitions — the free-form contract fields placed via
// FieldsPalette.vue and rendered on the canvas by FieldOverlay.vue. One
// source of truth so the palette and the rendered field always agree on
// icon/label/default size per type.
import {
  Signature,
  CaseSensitive,
  TextCursorInput,
  CalendarDays,
  Upload,
  ChevronDown,
  CircleDot,
  SquareCheck,
} from "lucide-vue-next";

// width/height are 0–1 fractions of the page, matching how a field's x/y/
// width/height are stored (see useDocumentEditorStore's addField).
// keyPrefix seeds the auto-generated Field ID (e.g. "CollectFile1"), same
// convention PandaDoc uses — useDocumentEditorStore's addField appends the
// count of same-type fields already on the document.
export const FIELD_TYPES = [
  { type: "signature", label: "Signature", icon: Signature, width: 0.22, height: 0.05, keyPrefix: "Signature" },
  { type: "initials", label: "Initials", icon: CaseSensitive, width: 0.1, height: 0.05, keyPrefix: "Initials" },
  { type: "text", label: "Text Field", icon: TextCursorInput, width: 0.22, height: 0.04, keyPrefix: "TextField" },
  { type: "date", label: "Date", icon: CalendarDays, width: 0.16, height: 0.04, keyPrefix: "Date" },
  { type: "file", label: "File Upload", icon: Upload, width: 0.2, height: 0.05, keyPrefix: "CollectFile" },
  { type: "dropdown", label: "Dropdown", icon: ChevronDown, width: 0.2, height: 0.04, keyPrefix: "Dropdown" },
  { type: "radio", label: "Radio Buttons", icon: CircleDot, width: 0.18, height: 0.04, keyPrefix: "RadioGroup" },
  { type: "checkbox", label: "Checkbox", icon: SquareCheck, width: 0.06, height: 0.04, keyPrefix: "Checkbox" },
];

const DEFAULT_PLACEHOLDERS = {
  signature: "Sign here",
  initials: "Initial here",
  text: "Enter value...",
  date: "Select a date",
  file: "Click to upload a file",
  dropdown: "Select an option",
  radio: "Select an option",
  checkbox: "",
};

export function defaultPlaceholder(type) {
  return DEFAULT_PLACEHOLDERS[type] ?? "";
}

// Only multi-choice types (radio, dropdown) carry an options list — a fresh
// one starts with two, same as PandaDoc, so there's immediately something to
// rename/remove rather than an empty list with just an "Add option" button.
export function defaultOptions(type) {
  return type === "radio" || type === "dropdown" ? ["Option 1", "Option 2"] : [];
}

export function fieldTypeDef(type) {
  return FIELD_TYPES.find((f) => f.type === type) ?? FIELD_TYPES[0];
}

export const PAGE_HEIGHT_PX = 1123;

export const PAGE_MARGIN_PX = 12;

export function clampFieldPosition(x, y, width, height, rect) {
  const marginX = rect?.width ? PAGE_MARGIN_PX / rect.width : 0;
  const marginY = rect?.height ? PAGE_MARGIN_PX / rect.height : 0;
  const heightFraction = rect?.height ? (height * PAGE_HEIGHT_PX) / rect.height : height;
  return {
    x: Math.min(Math.max(x, marginX), Math.max(marginX, 1 - width - marginX)),
    y: Math.min(Math.max(y, marginY), Math.max(marginY, 1 - heightFraction - marginY)),
  };
}
