<script setup lang="ts">
import { ref, computed, watch, onBeforeUnmount } from "vue";
import { X, ChevronLeft, ChevronRight, Info } from "lucide-vue-next";
import FusionPillSelect from "./FusionPillSelect.vue";
import FusionPillMultiSelect from "./FusionPillMultiSelect.vue";
import FusionTagInput from "./FusionTagInput.vue";
import FusionButton from "@/components/button/FusionButton.vue";
import FusionTextInput from "@/components/TextInput/FusionTextInput.vue";
import FusionAutocomplete from "@/components/autocomplete/FusionAutocomplete.vue";
type StepType =
  | "pill-single"
  | "pill-multi"
  | "tag-input"
  | "text"
  | "select"
  | "transition";
interface Option {
  value: string | number;
  label: string;
  icon?: any;
}
interface Step {
  id: string;
  type: StepType;
  question: string;
  options?: Option[];
  searchable?: boolean;
  placeholder?: string;
  multiple?: boolean;
  hint?: string;
  helperText?: string;
  validate?: "email" | ((value: string) => boolean);
  /** Auto-advance to the next step the instant an answer is given.
      Defaults to true for pill-single, false for everything else. */
  autoAdvance?: boolean;
  /** transition steps only — ms to wait before auto-advancing. Default 1500. */
  duration?: number;
  /** Overrides the Next button's label just for this step (e.g. "Invite", "Finish") */
  nextLabel?: string;
  /** Defaults to true. Set false to let Next stay enabled even with no answer —
      e.g. the "invite people" step shouldn't block someone who wants to skip it.
      When the user advances past a required:false step with no answer, the
      `skip` event fires so the app can react (e.g. show a "you can always
      invite teammates later" modal) without blocking the wizard itself. */
  required?: boolean;
}

const selectModel = computed(() => {
  const step = currentStepConfig.value;
  if (!step || step.type !== "select") return null;
  const stored = answers.value[step.id];
  if (stored === undefined || stored === null) return null;
  const opts = step.options ?? [];
  // If options are objects, find the one matching stored value; otherwise return null
  const found = opts.find((o: any) => String(o.value) === String(stored));
  return found ?? null;
});

interface Props {
  steps: Step[];
  step?: number;
  answers?: Record<string, any>;
  footerNote?: string;
  color?: string;
  /** Optional full-page background image URL, painted behind a dark scrim
      so the card content stays readable — same look as the reference flow's
      backdrop, but this is real page content, not a fixed modal overlay. */
  backdropImage?: string;
}
const props = withDefaults(defineProps<Props>(), {
  step: 0,
  answers: () => ({}),
  footerNote: "",
  color: undefined,
  backdropImage: "",
});
const emit = defineEmits<{
  (e: "update:step", value: number): void;
  (e: "update:answers", value: Record<string, any>): void;
  (e: "complete", answers: Record<string, any>): void;
  (e: "close"): void;
  /** Fired when the user clicks Next past a required:false step that has no
      answer — the app can catch this to trigger its own follow-up (e.g. a
      modal), separate from the wizard's own progression. */
  (e: "skip", payload: { id: string; type: StepType }): void;
}>();
const currentStep = ref(props.step);
const answers = ref({ ...props.answers });
watch(
  () => props.step,
  (v) => (currentStep.value = v)
);
const currentStepConfig = computed(() => props.steps[currentStep.value]);
// Transition steps have no nav (no Back/Next), so they need to move
// themselves forward — e.g. "Almost there..." auto-advances after a beat.
let transitionTimer: ReturnType<typeof setTimeout> | null = null;
watch(
  currentStepConfig,
  (step) => {
    if (transitionTimer) {
      clearTimeout(transitionTimer);
      transitionTimer = null;
    }
    if (step?.type === "transition") {
      transitionTimer = setTimeout(() => next(), step.duration ?? 1500);
    }
  },
  { immediate: true }
);
onBeforeUnmount(() => {
  if (transitionTimer) clearTimeout(transitionTimer);
});
const progressPct = computed(() => ((currentStep.value + 1) / props.steps.length) * 100);
const canAdvance = computed(() => {
  const step = currentStepConfig.value;
  if (!step) return false;
  if (step.type === "transition") return true;
  if (step.required === false) return true;
  const value = answers.value[step.id];
  if (step.type === "pill-single") return value !== undefined && value !== null;
  if (step.type === "pill-multi") return Array.isArray(value) && value.length > 0;
  if (step.type === "tag-input") return Array.isArray(value) && value.length > 0;
  if (step.type === "text") return typeof value === "string" && value.trim().length > 0;
  if (step.type === "select") {
    return value !== undefined && value !== null;
  }
  return true;
});
const nextLabel = computed(() => {
  const step = currentStepConfig.value;
  if (step?.nextLabel) return step.nextLabel;
  return currentStep.value === props.steps.length - 1 ? "Finish" : "Next";
});
const typeformStyle = computed(() =>
  props.color ? { "--fu-typeform-color": props.color } : {}
);
// Mirrors ClickUp's own inline style exactly:
// background: url(...) left top / cover no-repeat fixed;
const pageStyle = computed(() =>
  props.backdropImage
    ? {
        backgroundImage: `url(${props.backdropImage})`,
        backgroundPosition: "left top",
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        // Dropped `backgroundAttachment: "fixed"` — it silently breaks (image
        // can vanish entirely) if ANY ancestor has transform/filter/perspective/
        // will-change set, which route-transition wrappers almost always do.
        // Not worth chasing for a one-off onboarding background.
      }
    : {}
);
function onAnswer(value: any) {
  const step = currentStepConfig.value;
  if (!step) return;

  const answer = step.type === "select" ? value?.value : value;

  answers.value = {
    ...answers.value,
    [step.id]: answer,
  };

  emit("update:answers", answers.value);

  const shouldAutoAdvance = step.autoAdvance ?? step.type === "pill-single";

  if (shouldAutoAdvance) next();
}
function back() {
  if (currentStep.value === 0) return;
  currentStep.value -= 1;
  emit("update:step", currentStep.value);
}
function isStepEmpty(step: Step, value: any): boolean {
