<template>
  <Teleport to="body">
    <Transition name="mad">
      <div v-if="open" class="mad-overlay" @click.self="$emit('close')">
        <div class="mad-panel" role="dialog" aria-modal="true">
          <!-- Header -->
          <div class="mad-header">
            <div>
              <h3 class="mad-title">{{ title }}</h3>
              <p v-if="author" class="mad-author">by {{ author }}</p>
            </div>
            <button type="button" class="mad-close" @click="$emit('close')" aria-label="Close">
              <X :size="18" />
            </button>
          </div>

          <!-- Body -->
          <div class="mad-body">
            <section class="mad-section">
              <h4 class="mad-section__label">Recipients</h4>
              <div class="mad-recipients">
                <span
                  v-for="r in recipients"
                  :key="r.id"
                  class="mad-avatar"
                  :style="{ backgroundColor: r.color }"
                  :title="r.name"
                >
                  {{ initialsFor(r.name) }}
                </span>
              </div>
            </section>

            <section class="mad-section">
              <h4 class="mad-section__label">Actions</h4>
              <button
                v-for="a in actions"
                :key="a.label"
                type="button"
                class="mad-row"
                @click="a.action"
              >
                <component :is="a.icon" :size="18" />
                <span>{{ a.label }}</span>
              </button>
            </section>

            <section class="mad-section">
              <h4 class="mad-section__label">Other</h4>
              <button type="button" class="mad-row" @click="$emit('toggle-documents')">
                <Files :size="18" />
                <span>Documents</span>
              </button>
            </section>
          </div>

          <!-- Footer -->
          <div class="mad-footer">
            <button type="button" class="mad-decline" @click="$emit('decline')">
              <Ban :size="16" />
              Decline
            </button>
          </div>
        </div>
      </div>
    </Transition>
  </Teleport>
</template>

<script setup>
import { X, Download, Printer, Cookie, Files, Ban } from "lucide-vue-next";

defineProps({
  open: { type: Boolean, default: false },
  title: { type: String, default: "" },
  author: { type: String, default: "" },
  recipients: { type: Array, default: () => [] },
});
const emit = defineEmits(["close", "toggle-documents", "decline", "download"]);

function initialsFor(name) {
  const parts = (name || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return (parts[0][0] + (parts[1]?.[0] || "")).toUpperCase();
}

const actions = [
  { label: "Download", icon: Download, action: () => emit("download") },
  { label: "Print", icon: Printer, action: () => window.print() },
  { label: "Cookie preferences", icon: Cookie, action: () => {} },
];
</script>

