<template>
  <div class="fu-form-render" :style="themeStyle">
    <div class="fu-form-render__progress-track">
      <div class="fu-form-render__progress-fill" :style="{ width: progressPct + '%' }" />
    </div>

    <div class="fu-form-render__stage">
      <transition name="fu-form-render-slide" mode="out-in">
        <div v-if="renderedStep" :key="renderedStep.id" class="fu-form-render__step">
          <template v-if="renderedStep.kind === 'review'">
            <slot name="review" :answers="answers" :submit="submitForm" />
          </template>

          <template v-else>
            <BlockRenderer
              :block="renderedStep.block"
              :theme="theme"
              @action="handleAction"
            />

            <div v-if="!hasSubmitted" class="fu-form-render__ok-row">
              <FusionButton
                :text="isLastStep ? 'Submit' : 'OK'"
                variant="solid"
                size="lg"
                :disabled="!canAdvance"
                @click="isLastStep ? submitForm() : advance()"
              />
              <span class="fu-form-render__ok-hint">
                <template v-if="isLastStep">
                  press <strong>{{ modKeyLabel }}</strong> + <strong>Enter ↵</strong>
                </template>
                <template v-else> press <strong>Enter ↵</strong> </template>
              </span>
            </div>
          </template>
        </div>
      </transition>
    </div>

    <div v-if="!hasSubmitted" class="fu-form-render__nav">
      <div class="fu-form-render__nav-group">
        <FusionActionButton
          :icon="ChevronUp"
          variant="subtle"
          size="md"
          tooltip="Previous"
          :disabled="stepPos === 0"
          @click="back"
        />
        <FusionActionButton
          :icon="ChevronDown"
          variant="solid"
          size="md"
          tooltip="Next"
          :disabled="!canAdvance || isLastStep || isReviewStep"
          @click="advance"
        />
      </div>

      <slot name="branding" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, useSlots } from "vue";
import { ChevronUp, ChevronDown } from "lucide-vue-next";
import BlockRenderer from "../blockContent/BlockRenderer.vue";
import FusionActionButton from "@/components/actionButton/FusionActionButton.vue";
import FusionButton from "@/components/button/FusionButton.vue";

const props = defineProps<{
  document: any;
}>();

const emit = defineEmits<{
  (e: "submit", answers: Record<string, any>): void;
}>();

const slots = useSlots();

const theme = computed(() => props.document?.meta?.theme || {});

const themeStyle = computed(() => ({
  "--brand-color": theme.value.brandColor || "#4362FF",
  "--accent-color": theme.value.accentColor || "#E0E7FF",
}));

const modKeyLabel = computed(() => {
  if (typeof navigator === "undefined") return "Ctrl";
  return /Mac|iPhone|iPad|iPod/.test(navigator.userAgent) ? "Cmd ⌘" : "Ctrl";
});

function styleOf(block: any) {
  return {
    backgroundColor: block.backgroundColor,
    backgroundOpacity: block.backgroundOpacity,
    backgroundImage: block.backgroundImage,
    contentWidth: block.contentWidth,
    paddingTop: block.paddingTop,
    paddingBottom: block.paddingBottom,
  };
}

function syntheticBlock(block: any, id: string, widgets: any[]) {
  return { ...styleOf(block), id, columns: [{ width: 100, widgets }] };
}

type Step = { kind: "block"; id: string; block: any } | { kind: "review"; id: string };

const questionWidgetsById = computed(() => {
  const map: Record<string, any> = {};
  for (const page of props.document?.pages ?? []) {
    for (const block of page.blocks ?? []) {
      for (const col of block.columns ?? []) {
        for (const w of col.widgets ?? []) {
          if (w.type === "question") map[w.id] = w;
        }
      }
    }
  }
  return map;
});

function resolveComparableValue(widgetId: string) {
  const raw = answers.value[widgetId];
  const widget = questionWidgetsById.value[widgetId];
  const opt = widget?.props?.options?.find((o: any) => o.id === raw);
  return opt ? opt.text : raw;
}

function evaluateCondition(cond: any) {
  const actual = resolveComparableValue(cond.sourceWidgetId);
  if (cond.operator === "equals") return actual === cond.value;
  if (cond.operator === "not_equals") return actual !== cond.value;
  return true;
}

function isQuestionVisible(widget: any): boolean {
  const conditions = widget.props?.conditions || [];
  if (!conditions.length) return true;
  const logic = widget.props?.conditionLogic || "all";
  const results = conditions.map(evaluateCondition);
  return logic === "any" ? results.some(Boolean) : results.every(Boolean);
}

function blockQuestionWidgets(block: any) {
  return (block.columns ?? [])
    .flatMap((c: any) => c.widgets ?? [])
    .filter((w: any) => w.type === "question");
}

const allSteps = computed<Step[]>(() => {
  const pages = props.document?.pages ?? [];
  const steps: Step[] = [];

  for (const page of pages) {
    for (const block of page.blocks ?? []) {
      const isMultiColumn = (block.columns ?? []).length > 1;

      if (isMultiColumn) {
        steps.push({ kind: "block", id: block.id, block });
        continue;
      }

      const widgets = block.columns?.[0]?.widgets ?? [];
      const questionWidgets = widgets.filter((w: any) => w.type === "question");
      const contentWidgets = widgets.filter((w: any) => w.type !== "question");

      if (questionWidgets.length === 0) {
        if (contentWidgets.length) {
          steps.push({
            kind: "block",
            id: `${block.id}-content`,
            block: syntheticBlock(block, `${block.id}-content`, contentWidgets),
          });
        }
        continue;
      }

      if (contentWidgets.length) {
        steps.push({
          kind: "block",
          id: `${block.id}-content`,
          block: syntheticBlock(block, `${block.id}-content`, contentWidgets),
        });
      }

      for (const w of questionWidgets) {
        steps.push({
          kind: "block",
          id: w.id,
          block: syntheticBlock(block, `${block.id}-${w.id}`, [w]),
        });
      }
    }
  }

  return steps;
});

function stepQuestionWidgets(step: Step) {
  if (step.kind !== "block") return [];
  return blockQuestionWidgets(step.block).filter(isQuestionVisible);
}

const answers = ref<Record<string, any>>({});

const visibleSteps = computed(() => {
  const filtered = allSteps.value.filter((step) => {
    if (step.kind !== "block") return true;
    const questions = blockQuestionWidgets(step.block);
    if (questions.length === 0) return true;
    return stepQuestionWidgets(step).length > 0;
  });

  if (!slots.review) return filtered;

  const hasQuestions = (s: Step) =>
    s.kind === "block" && stepQuestionWidgets(s).length > 0;
  const lastQuestionFromEnd = [...filtered].reverse().findIndex(hasQuestions);
  if (lastQuestionFromEnd === -1) return filtered;

  const insertAt = filtered.length - lastQuestionFromEnd;
  const reviewStep: Step = { kind: "review", id: "__fu-form-render-review__" };
  return [...filtered.slice(0, insertAt), reviewStep, ...filtered.slice(insertAt)];
});

const hasSubmitted = ref(false);
const stepIndex = ref(0);

const stepPos = computed(() =>
  Math.min(stepIndex.value, Math.max(visibleSteps.value.length - 1, 0))
);
const currentStep = computed(() => visibleSteps.value[stepPos.value] ?? null);
const isLastStep = computed(() => stepPos.value === visibleSteps.value.length - 1);
const isReviewStep = computed(() => currentStep.value?.kind === "review");

function visibleBlock(block: any) {
  return {
    ...block,
    columns: (block.columns ?? []).map((col: any) => ({
      ...col,
      widgets: (col.widgets ?? []).filter(
        (w: any) => w.type !== "question" || isQuestionVisible(w)
      ),
    })),
  };
}

const renderedStep = computed(() => {
  const step = currentStep.value;
  if (!step || step.kind !== "block") return step;

  const patchedBlock = visibleBlock(step.block);
  patchedBlock.columns = patchedBlock.columns.map((col: any) => ({
    ...col,
    widgets: col.widgets.map((w: any) => {
      if (w.type !== "question") return w;
      const answeredValue = answers.value[w.id];
      if (answeredValue === undefined) return w;
      return { ...w, props: { ...w.props, value: answeredValue } };
    }),
  }));

  return { ...step, block: patchedBlock };
});

const progressPct = computed(() => {
  if (!visibleSteps.value.length) return 0;
  return Math.min(100, ((stepPos.value + 1) / visibleSteps.value.length) * 100);
});

function isEmptyAnswer(questionType: string, val: any) {
  if (questionType === "multiple_choice") return !Array.isArray(val) || val.length === 0;
  if (questionType === "contact_details")
    return !val || !val.firstName?.trim() || !val.lastName?.trim();
  return val === null || val === undefined || val === "";
}

const canAdvance = computed(() => {
  const step = currentStep.value;
  if (!step || step.kind !== "block") return true;
  return stepQuestionWidgets(step).every((w: any) => {
    if (!w.props.required) return true;
    return !isEmptyAnswer(w.props.questionType, answers.value[w.id]);
  });
});

function advance() {
  if (!canAdvance.value || isLastStep.value || isReviewStep.value) return;
  stepIndex.value += 1;
}

function back() {
  if (stepIndex.value > 0) stepIndex.value -= 1;
}

function submitForm() {
  if (!canAdvance.value) return;
  hasSubmitted.value = true;
  emit("submit", { ...answers.value });
  if (stepPos.value < visibleSteps.value.length - 1) {
    stepIndex.value += 1;
  }
}

function handleKeydown(e: KeyboardEvent) {
  if (hasSubmitted.value || !currentStep.value) return;

  const modPressed = e.metaKey || e.ctrlKey;

  if (isLastStep.value || isReviewStep.value) {
    if (modPressed && e.key === "Enter") {
      e.preventDefault();
      submitForm();
    }
    return;
  }

  if (e.key === "Enter" && !e.shiftKey && !modPressed) {
    e.preventDefault();
    advance();
  }
}

onMounted(() => window.addEventListener("keydown", handleKeydown));
onBeforeUnmount(() => window.removeEventListener("keydown", handleKeydown));

function handleAction(action: any) {
  if (action?.type !== "update" || !action.widgetId) return;

  answers.value = { ...answers.value, [action.widgetId]: action.payload?.value };

  const step = currentStep.value;
  if (!step || step.kind !== "block" || isLastStep.value) return;

  const visibleQuestions = stepQuestionWidgets(step);
  if (visibleQuestions.length !== 1) return;

  const widget = visibleQuestions[0];
  if (widget.id !== action.widgetId || widget.props.questionType !== "single_choice")
    return;

  const val = action.payload?.value;
  const hasValue = val !== null && val !== undefined && val !== "";
  if (!hasValue) return;

  setTimeout(() => {
    if (currentStep.value === step) advance();
  }, 350);
}
</script>

