// Recipient colors are STORED DATA — each recipient carries its own `color`
// (recipient.color, from the backend / mock JSON, same as PandaDoc assigns
// one per signer), not something derived from the id. These helpers look
// that up; they don't invent a color when one already exists.

function hueForRecipient(recipientId) {
  const str = String(recipientId ?? "");
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0; // keep it a 32-bit int
  }
  return Math.abs(hash) % 360;
}

const FALLBACK_HUE = 220; // neutral slate-blue — no recipient selected yet

// Fallback ONLY, for a recipient record that has no explicit `color` set —
// keeps it visually distinct from other un-colored recipients rather than
// every one of them landing on the same flat gray.
function hashColor(recipientId) {
  const hue = recipientId ? hueForRecipient(recipientId) : FALLBACK_HUE;
  return `hsl(${hue}, 70%, 42%)`;
}

// Source of truth: the recipient's own stored color. `recipients` is the
// list to look it up in (store.contractRecipients) — pass the id, not the
// whole recipient object, since that's what fields/drag payloads carry.
export function resolveRecipientColor(recipients, recipientId) {
  if (!recipientId) return hashColor(null);
  const r = (recipients || []).find((x) => String(x.id) === String(recipientId));
  return r?.color || hashColor(recipientId);
}

// Light fill tint of a resolved color, for a field/card's background.
export function bgTint(hex) {
  return `color-mix(in srgb, ${hex} 18%, white)`;
}

// Mirrors the backend's RecipientRole::mustSign() (skkido-backend
// app/Enums/Contracts/RecipientRole.php) — only 'signer' ever fills or
// signs a field; 'approver' and 'viewer' review only. Missing role treated
// as permissive (signer) for backward compatibility with recipient objects
// that don't carry one.
export function canRecipientAct(recipient) {
  return !recipient?.role || recipient.role === "signer";
}
