<template>
  <div
    class="fu-pill-select"
    :class="[`fu-pill-select--${size}`]"
    role="radiogroup"
    :style="typeformStyle"
  >
    <button
      v-for="opt in options"
      :key="opt.value"
      type="button"
      class="fu-pill"
      :class="{
        'is-selected': modelValue === opt.value,
        'is-readonly': readonly,
      }"
      :disabled="disabled"
      role="radio"
      :aria-checked="modelValue === opt.value"
      @click="select(opt.value)"
    >
      <img
        v-if="typeof opt.icon === 'string'"
        :src="opt.icon"
        class="fu-pill__icon-img"
        alt=""
      />
      <component v-else-if="opt.icon" :is="opt.icon" :size="16" class="fu-pill__icon" />
      <span>{{ opt.label }}</span>
    </button>
  </div>
</template>

<script setup lang="ts">
import { computed } from "vue";

type Size = "sm" | "md" | "lg";

interface Option {
  value: string | number;
  label: string;
  /** A Lucide icon component, OR an image URL string — both are supported. */
  icon?: any;
}

interface Props {
  modelValue?: string | number | null;
  options: Option[];
  size?: Size;
  disabled?: boolean;
  readonly?: boolean;

  /* Same naming/behavior as FusionTextInput/FusionRadio's typeform styling —
     drives the selected pill's fill color and the group's font. */
  font?: string;
  fontSize?: string;
  color?: string;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: null,
  size: "md",
  disabled: false,
  readonly: false,
  font: undefined,
  fontSize: undefined,
  color: undefined,
});

const emit = defineEmits<{
  (e: "update:modelValue", value: string | number): void;
}>();

function select(value: string | number) {
  if (props.disabled || props.readonly) return;
  emit("update:modelValue", value);
}

const typeformStyle = computed(() => ({
  ...(props.font ? { "--fu-typeform-font": props.font } : {}),
  ...(props.fontSize ? { "--fu-typeform-font-size": props.fontSize } : {}),
  ...(props.color ? { "--fu-typeform-color": props.color } : {}),
}));
</script>

<style scoped lang="scss">
.fu-pill-select {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-family: var(--fu-typeform-font, inherit);
  font-size: var(--fu-typeform-font-size, inherit);
}

.fu-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border-radius: 999px;
  border: 1px solid var(--fu-border);
  background: transparent;
  color: var(--fu-color-text);
  font-family: inherit;
  font-size: inherit;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  white-space: nowrap;

  &:hover:not(:disabled):not(.is-selected) {
    border-color: var(--fu-color-text-light, #9ca3af);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  &.is-readonly {
    cursor: default;
  }

  &.is-selected {
    background: var(--fu-form-control);
    border-color: var(--fu-typeform-color);
  }
}

/* Sizes — heights match the ~44px pill from the reference flow at md */
.fu-pill-select--sm .fu-pill {
  height: 36px;
  padding: 0 16px;
  font-size: 13px;
}
.fu-pill-select--md .fu-pill {
  height: 44px;
  padding: 0 20px;
  font-size: 15px;
}
.fu-pill-select--lg .fu-pill {
  height: 52px;
  padding: 0 24px;
  font-size: 17px;
}

.fu-pill__icon-img {
  width: 16px;
  height: 16px;
  object-fit: contain;
  flex-shrink: 0;
}
</style>
